INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (501, 'tt0089218', 9340, 'The Goonies', 1985, '/eBU7gCjTCj9n2LTxvCSIXXOvHkD.jpg', '{12,35,10751}', 'Young teen Mikey Walsh and his friends set off on a quest to find Pirate One-Eyed Willie''s treasure in hopes of saving their homes from demolition. However, on their quest to find the treasure, they run into a family of recently escaped criminals, determined to capture the kids and reach the treasure first.', '[{"name": "Sean Astin", "character": "Mikey"}, {"name": "Josh Brolin", "character": "Brand"}, {"name": "Jeff Cohen", "character": "Chunk"}, {"name": "Corey Feldman", "character": "Mouth"}, {"name": "Kerri Green", "character": "Andy"}]', 'Richard Donner', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (502, 'tt0092099', 744, 'Top Gun', 1986, '/xUuHj3CgmZQ9P2cMaqQs4J0d4Zc.jpg', '{28,18,10749}', 'For Lieutenant Pete ''Maverick'' Mitchell and his friend and co-pilot Nick ''Goose'' Bradshaw, being accepted into an elite training school for fighter pilots is a dream come true. But a tragedy, as well as personal demons, will threaten Pete''s dreams of becoming an ace pilot.', '[{"name": "Tom Cruise", "character": "Maverick"}, {"name": "Kelly McGillis", "character": "Charlie"}, {"name": "Val Kilmer", "character": "Ice"}, {"name": "Anthony Edwards", "character": "Goose"}, {"name": "Tom Skerritt", "character": "Viper"}]', 'Tony Scott', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (503, 'tt0093870', 5548, 'RoboCop', 1987, '/hHtOgGb3NihlyRATHlKPaFApbrd.jpg', '{28,53,878}', 'In a violent, near-apocalyptic Detroit, evil corporation Omni Consumer Products wins a contract from the city government to privatize the police force. To test their crime-eradicating cyborgs, the company leads street cop Alex Murphy into an armed confrontation with crime lord Boddicker so they can use his body to support their untested RoboCop prototype. But when RoboCop learns of the company''s nefarious plans, he turns on his masters.', '[{"name": "Peter Weller", "character": "Officer Alex J. Murphy / RoboCop"}, {"name": "Nancy Allen", "character": "Officer Anne Lewis"}, {"name": "Dan O''Herlihy", "character": "The Old Man"}, {"name": "Ronny Cox", "character": "Dick Jones"}, {"name": "Kurtwood Smith", "character": "Clarence Boddicker"}]', 'Paul Verhoeven', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (504, 'tt0094737', 2280, 'Big', 1988, '/eWhCDJiwxvx3YXkAFRiHjimnF0j.jpg', '{14,18,35}', 'When a young boy makes a wish at a carnival machine to be big—he wakes up the following morning to find that it has been granted and his body has grown older overnight. But he is still the same 13-year-old boy inside. Now he must learn how to cope with the unfamiliar world of grown-ups including getting a job and having his first romantic encounter with a woman.', '[{"name": "Tom Hanks", "character": "Josh Baskin"}, {"name": "Elizabeth Perkins", "character": "Susan"}, {"name": "Robert Loggia", "character": "MacMillan"}, {"name": "John Heard", "character": "Paul"}, {"name": "Jared Rushton", "character": "Billy"}]', 'Penny Marshall', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (505, 'tt0096895', 268, 'Batman', 1989, '/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', '{14,28,80}', 'Having witnessed his parents'' brutal murder as a child, millionaire philanthropist Bruce Wayne fights crime in Gotham City disguised as Batman, a costumed hero who strikes fear into the hearts of villains. But when a deformed madman known as ''The Joker'' seizes control of Gotham''s criminal underworld, Batman must face his most ruthless nemesis ever while protecting both his identity and his love interest, reporter Vicki Vale.', '[{"name": "Michael Keaton", "character": "Batman / Bruce Wayne"}, {"name": "Jack Nicholson", "character": "Joker / Jack Napier"}, {"name": "Kim Basinger", "character": "Vicki Vale"}, {"name": "Robert Wuhl", "character": "Alexander Knox"}, {"name": "Pat Hingle", "character": "Commissioner Gordon"}]', 'Tim Burton', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (506, 'tt0098635', 639, 'When Harry Met Sally...', 1989, '/rFOiFUhTMtDetqCGClC9PIgnC1P.jpg', '{35,10749,18}', 'Sex always gets in the way of friendships between men and women. At least, that''s what Harry Burns believes. So when Harry meets Sally Albright and a deep friendship blossoms between them, Harry''s determined not to let his attraction to Sally destroy it. But when a night of weakness ends in a morning of panic, can the pair avoid succumbing to Harry''s fears by remaining friends and admitting they just might be the perfect match for each other?', '[{"name": "Billy Crystal", "character": "Harry Burns"}, {"name": "Meg Ryan", "character": "Sally Albright"}, {"name": "Carrie Fisher", "character": "Marie"}, {"name": "Bruno Kirby", "character": "Jess"}, {"name": "Steven Ford", "character": "Joe"}]', 'Rob Reiner', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (507, 'tt0111257', 1637, 'Speed', 1994, '/82PkCE4R95KhHICUDF7G4Ly2z3l.jpg', '{28,53}', 'Tensions run high when a crazed bomber rigs a Los Angeles bus with a device that will kill everyone on board if the vehicle''s speed dips below fifty miles per hour.', '[{"name": "Keanu Reeves", "character": "Jack Traven"}, {"name": "Dennis Hopper", "character": "Howard Payne"}, {"name": "Sandra Bullock", "character": "Annie"}, {"name": "Joe Morton", "character": "Capt. McMahon"}, {"name": "Jeff Daniels", "character": "Harry"}]', 'Jan de Bont', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (508, 'tt0116629', 602, 'Independence Day', 1996, '/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg', '{28,12,878}', 'Strange phenomena surface around the globe. The skies ignite. Terror races through the world''s major cities. As these extraordinary events unfold, it becomes increasingly clear that a force of incredible magnitude has arrived. Its mission: total annihilation over the Fourth of July weekend. The last hope to stop the destruction is an unlikely group of people united by fate and unimaginable circumstances.', '[{"name": "Will Smith", "character": "Capt. Steven Hiller"}, {"name": "Bill Pullman", "character": "President Thomas J. Whitmore"}, {"name": "Jeff Goldblum", "character": "David Levinson"}, {"name": "Mary McDonnell", "character": "Marilyn Whitmore"}, {"name": "Judd Hirsch", "character": "Julius Levinson"}]', 'Roland Emmerich', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (509, 'tt0116695', 9390, 'Jerry Maguire', 1996, '/lABvGN7fDk5ifnwZoxij6G96t2w.jpg', '{35,18,10749}', 'Jerry Maguire used to be a typical sports agent: willing to do just about anything he could to get the biggest possible contracts for his clients, plus a nice commission for himself. Then, one day, he suddenly has second thoughts about what he''s really doing. When he voices these doubts, he ends up losing his job and all of his clients, save Rod Tidwell, an egomaniacal football player.', '[{"name": "Tom Cruise", "character": "Jerry Maguire"}, {"name": "Renée Zellweger", "character": "Dorothy Boyd"}, {"name": "Cuba Gooding Jr.", "character": "Rod Tidwell"}, {"name": "Kelly Preston", "character": "Avery Bishop"}, {"name": "Jerry O''Connell", "character": "Frank Cushman"}]', 'Cameron Crowe', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (510, 'tt0119116', 18, 'The Fifth Element', 1997, '/fPtlCO1yQtnoLHOwKtWz7db6RGU.jpg', '{878,28,12}', 'In 2257, a taxi driver is unintentionally given the task of saving a young girl who is part of the key that will ensure the survival of humanity.', '[{"name": "Bruce Willis", "character": "Korben Dallas"}, {"name": "Milla Jovovich", "character": "Leeloo"}, {"name": "Gary Oldman", "character": "Zorg"}, {"name": "Ian Holm", "character": "Cornelius"}, {"name": "Chris Tucker", "character": "Ruby Rhod"}]', 'Luc Besson', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (511, 'tt0119654', 607, 'Men in Black', 1997, '/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg', '{28,12,35,878}', 'After a police chase with an otherworldly being, a New York City cop is recruited as an agent in a top-secret organization established to monitor and police alien activity on Earth: the Men in Black. Agent K and new recruit Agent J find themselves in the middle of a deadly plot by an intergalactic terrorist who has arrived on Earth to assassinate two ambassadors from opposing galaxies.', '[{"name": "Tommy Lee Jones", "character": "Kay"}, {"name": "Will Smith", "character": "Jay"}, {"name": "Linda Fiorentino", "character": "Laurel"}, {"name": "Vincent D''Onofrio", "character": "Edgar"}, {"name": "Rip Torn", "character": "Zed"}]', 'Barry Sonnenfeld', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (512, 'tt0120601', 492, 'Being John Malkovich', 1999, '/31FGQu3OnwdmS4COquENe0vMZc0.jpg', '{35,18,14}', 'One day at work, unsuccessful puppeteer Craig finds a portal into the head of actor John Malkovich. The portal soon becomes a passion for anybody who enters its mad and controlling world of overtaking another human body.', '[{"name": "John Cusack", "character": "Craig Schwartz"}, {"name": "Cameron Diaz", "character": "Lotte Schwartz"}, {"name": "John Malkovich", "character": "John Horatio Malkovich"}, {"name": "Catherine Keener", "character": "Maxine Lund"}, {"name": "Orson Bean", "character": "Dr. Lester"}]', 'Spike Jonze', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (513, 'tt0125439', 509, 'Notting Hill', 1999, '/hHRIf2XHeQMbyRb3HUx19SF5Ujw.jpg', '{10749,35}', 'London bookstore owner William Thacker''s quiet life turns upside down when a chance encounter with famous actress Anna Scott sparks an unlikely romance challenged by their vastly different worlds.', '[{"name": "Julia Roberts", "character": "Anna Scott"}, {"name": "Hugh Grant", "character": "William Thacker"}, {"name": "Gina McKee", "character": "Bella"}, {"name": "Tim McInnerny", "character": "Max"}, {"name": "Rhys Ifans", "character": "Spike"}]', 'Roger Michell', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (514, 'tt0120915', 1893, 'Star Wars: Episode I - The Phantom Menace', 1999, '/xQzMnuiv81d0gfUIVstuleNutjA.jpg', '{12,28,878}', 'Anakin Skywalker, a young slave strong with the Force, is discovered on Tatooine. Meanwhile, the evil Sith have returned, enacting their plot for revenge against the Jedi.', '[{"name": "Liam Neeson", "character": "Qui-Gon Jinn"}, {"name": "Ewan McGregor", "character": "Obi-Wan Kenobi"}, {"name": "Natalie Portman", "character": "Padmé Amidala"}, {"name": "Jake Lloyd", "character": "Anakin Skywalker"}, {"name": "Ian McDiarmid", "character": "Senator Palpatine"}]', 'George Lucas', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (515, 'tt0241527', 671, 'Harry Potter and the Philosopher''s Stone', 2001, '/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', '{12,14}', 'Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.', '[{"name": "Daniel Radcliffe", "character": "Harry Potter"}, {"name": "Rupert Grint", "character": "Ron Weasley"}, {"name": "Emma Watson", "character": "Hermione Granger"}, {"name": "Richard Harris", "character": "Albus Dumbledore"}, {"name": "Tom Felton", "character": "Draco Malfoy"}]', 'Chris Columbus', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (516, 'tt0240772', 161, 'Ocean''s Eleven', 2001, '/hQQCdZrsHtZyR6NbKH2YyCqd2fR.jpg', '{53,80}', 'Less than 24 hours into his parole, charismatic thief Danny Ocean is already rolling out his next plan: In one night, Danny''s hand-picked crew of specialists will attempt to steal more than $150 million from three Las Vegas casinos. But to score the cash, Danny risks his chances of reconciling with ex-wife, Tess.', '[{"name": "George Clooney", "character": "Danny Ocean"}, {"name": "Brad Pitt", "character": "Rusty Ryan"}, {"name": "Andy Garcia", "character": "Terry Benedict"}, {"name": "Matt Damon", "character": "Linus Caldwell"}, {"name": "Julia Roberts", "character": "Tess Ocean"}]', 'Steven Soderbergh', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (517, 'tt0145487', 557, 'Spider-Man', 2002, '/kjdJntyBeEvqm9w97QGBdxPptzj.jpg', '{28,878}', 'After being bitten by a genetically altered spider at Oscorp, nerdy but endearing high school student Peter Parker is endowed with amazing powers to become the superhero known as Spider-Man.', '[{"name": "Tobey Maguire", "character": "Spider-Man / Peter Parker"}, {"name": "Willem Dafoe", "character": "Green Goblin / Norman Osborn"}, {"name": "Kirsten Dunst", "character": "Mary Jane Watson"}, {"name": "James Franco", "character": "Harry Osborn"}, {"name": "Cliff Robertson", "character": "Ben Parker"}]', 'Sam Raimi', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (518, 'tt0299658', 1574, 'Chicago', 2002, '/3ED8cWCXY9zkx77Sd0N5qMbsdDP.jpg', '{35,80,18}', 'Murderesses Velma Kelly and Roxie Hart find themselves on death row together and fight for the fame that will keep them from the gallows in 1920s Chicago.', '[{"name": "Renée Zellweger", "character": "Roxie Hart"}, {"name": "Catherine Zeta-Jones", "character": "Velma Kelly"}, {"name": "Richard Gere", "character": "Billy Flynn"}, {"name": "Queen Latifah", "character": "Matron Mama Morton"}, {"name": "Ekaterina Chtchelkanova", "character": "Katalin Helinski \"Hunyak\""}]', 'Rob Marshall', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (519, 'tt0298148', 809, 'Shrek 2', 2004, '/2yYP0PQjG8zVqturh1BAqu2Tixl.jpg', '{16,35,10751,14,10749}', 'Happily ever after never seemed so far far away when a trip to meet the in-laws turns into a hilariously twisted adventure for Shrek and Fiona. With the help of ever-faithful Donkey, Shrek takes on the potion-brewing Fairy Godmother, pompous Prince Charming, and infamous ogre-killer Puss In Boots.', '[{"name": "Mike Myers", "character": "Shrek (voice)"}, {"name": "Eddie Murphy", "character": "Donkey (voice)"}, {"name": "Cameron Diaz", "character": "Princess Fiona (voice)"}, {"name": "Julie Andrews", "character": "Queen Lillian (voice)"}, {"name": "Antonio Banderas", "character": "Puss in Boots (voice)"}]', 'Conrad Vernon', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (520, 'tt0416449', 1271, '300', 2007, '/h7Lcio0c9ohxPhSZg42eTlKIVVY.jpg', '{28,12,10752}', 'A story very loosely based the 480 B.C. Battle of Thermopylae, where the King of Sparta led his army against the advancing Persians.', '[{"name": "Gerard Butler", "character": "King Leonidas"}, {"name": "Lena Headey", "character": "Gorgo"}, {"name": "Dominic West", "character": "Theron"}, {"name": "David Wenham", "character": "Dilios/Narrator"}, {"name": "Vincent Regan", "character": "Captain"}]', 'Zack Snyder', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (521, 'tt0467406', 7326, 'Juno', 2007, '/jNIn2tVhpvFD6P9IojldI3mNYcn.jpg', '{35,18,10749}', 'Faced with an unplanned pregnancy, sixteen year old high-schooler, Juno MacGuff, makes an unusual decision regarding her unborn child.', '[{"name": "Elliot Page", "character": "Juno MacGuff"}, {"name": "Michael Cera", "character": "Paulie Bleeker"}, {"name": "Jennifer Garner", "character": "Vanessa Loring"}, {"name": "Jason Bateman", "character": "Mark Loring"}, {"name": "J.K. Simmons", "character": "Mac MacGuff"}]', 'Jason Reitman', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (522, 'tt1022603', 19913, '(500) Days of Summer', 2009, '/qXAuQ9hF30sQRsXf40OfRVl0MJZ.jpg', '{35,18,10749}', 'Tom, greeting-card writer and hopeless romantic, is caught completely off-guard when his girlfriend, Summer, suddenly dumps him. He reflects on their 500 days together to try to figure out where their love affair went sour, and in doing so, Tom rediscovers his true passions in life.', '[{"name": "Joseph Gordon-Levitt", "character": "Tom"}, {"name": "Zooey Deschanel", "character": "Summer"}, {"name": "Geoffrey Arend", "character": "McKenzie"}, {"name": "Chloë Grace Moretz", "character": "Rachel"}, {"name": "Matthew Gray Gubler", "character": "Paul"}]', 'Marc Webb', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (523, 'tt1605783', 59436, 'Midnight in Paris', 2011, '/4wBG5kbfagTQclETblPRRGihk0I.jpg', '{14,35,10749}', 'While on a trip to Paris with his fiancée''s family, a nostalgic screenwriter finds himself mysteriously going back to the 1920s every day at midnight.', '[{"name": "Owen Wilson", "character": "Gil"}, {"name": "Rachel McAdams", "character": "Inez"}, {"name": "Kathy Bates", "character": "Gertrude Stein"}, {"name": "Kurt Fuller", "character": "John"}, {"name": "Adrien Brody", "character": "Salvador Dalí"}]', 'Woody Allen', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (524, 'tt1045658', 82693, 'Silver Linings Playbook', 2012, '/fhHB1uvfFKKFbj6bTKE8xdtsjKi.jpg', '{18,35,10749}', 'After losing his job and wife, and spending time in an institution, a former teacher winds up living with his parents. He wants to rebuild his life and reconcile with his wife, but his father would be happy if he shared his obsession with the Philadelphia Eagles. Things get complicated when he meets Tiffany Maxwell who offers to help him reconnect with his wife if he will do something very important for her in exchange.', '[{"name": "Bradley Cooper", "character": "Pat Solatano Jr."}, {"name": "Jennifer Lawrence", "character": "Tiffany Maxwell"}, {"name": "Robert De Niro", "character": "Pat Solatano Sr."}, {"name": "Jacki Weaver", "character": "Dolores Solatano"}, {"name": "Anupam Kher", "character": "Dr. Cliff Patel"}]', 'David O. Russell', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (525, 'tt1024648', 68734, 'Argo', 2012, '/m5gPWFZFIp4UJFABgWyLkbXv8GX.jpg', '{18,53}', 'As the Iranian revolution reaches a boiling point, a CIA ''exfiltration'' specialist concocts a risky plan to free six Americans who have found shelter at the home of the Canadian ambassador.', '[{"name": "Ben Affleck", "character": "Tony Mendez"}, {"name": "Bryan Cranston", "character": "Jack O''Donnell"}, {"name": "Alan Arkin", "character": "Lester Siegel"}, {"name": "John Goodman", "character": "John Chambers"}, {"name": "Victor Garber", "character": "Ken Taylor"}]', 'Ben Affleck', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (526, 'tt1454468', 49047, 'Gravity', 2013, '/kZ2nZw8D681aphje8NJi8EfbL1U.jpg', '{878,53,18}', 'Dr Ryan Stone, an engineer on her first space mission, and Matt Kowalski, an astronaut on his final expedition, have to survive in space after they are hit by debris while spacewalking.', '[{"name": "Sandra Bullock", "character": "Ryan Stone"}, {"name": "George Clooney", "character": "Matt Kowalski"}, {"name": "Ed Harris", "character": "Mission Control (voice)"}, {"name": "Orto Ignatiussen", "character": "Aningaaq (voice)"}, {"name": "Phaldut Sharma", "character": "Shariff (voice)"}]', 'Alfonso Cuarón', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (527, 'tt4975722', 376867, 'Moonlight', 2016, '/qLnfEmPrDjJfPyyddLJPkXmshkp.jpg', '{18}', 'The tender, heartbreaking story of a young man’s struggle to find himself, told across three defining chapters in his life as he experiences the ecstasy, pain, and beauty of falling in love, while grappling with his own sexuality.', '[{"name": "Trevante Rhodes", "character": "Black"}, {"name": "André Holland", "character": "Kevin"}, {"name": "Janelle Monáe", "character": "Teresa"}, {"name": "Ashton Sanders", "character": "Chiron"}, {"name": "Jharrel Jerome", "character": "Kevin Age 16"}]', 'Barry Jenkins', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (528, 'tt1517451', 332562, 'A Star Is Born', 2018, '/wrFpXMNBRj2PBiN4Z5kix51XaIZ.jpg', '{10402,18,10749}', 'Seasoned musician Jackson Maine discovers — and falls in love with — struggling artist Ally. She has just about given up on her dream to make it big as a singer — until Jack coaxes her into the spotlight. But even as Ally''s career takes off, the personal side of their relationship is breaking down, as Jack fights an ongoing battle with his own internal demons.', '[{"name": "Lady Gaga", "character": "Ally Campana"}, {"name": "Bradley Cooper", "character": "Jackson Maine"}, {"name": "Sam Elliott", "character": "Bobby Maine"}, {"name": "Andrew Dice Clay", "character": "Lorenzo Campana"}, {"name": "Rafi Gavron", "character": "Rez Gavron"}]', 'Bradley Cooper', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (529, 'tt7131622', 466272, 'Once Upon a Time... in Hollywood', 2019, '/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', '{35,18,53}', 'Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…', '[{"name": "Leonardo DiCaprio", "character": "Rick Dalton"}, {"name": "Brad Pitt", "character": "Cliff Booth"}, {"name": "Margot Robbie", "character": "Sharon Tate"}, {"name": "Emile Hirsch", "character": "Jay Sebring"}, {"name": "Margaret Qualley", "character": "''Pussycat''"}]', 'Quentin Tarantino', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (530, 'tt9770150', 581734, 'Nomadland', 2021, '/8Vc5EOUEIF1EUXuX9eLFf7BvN3P.jpg', '{18}', 'A woman in her sixties embarks on a journey through the western United States after losing everything in the Great Recession, living as a van-dwelling modern-day nomad.', '[{"name": "Frances McDormand", "character": "Fern"}, {"name": "David Strathairn", "character": "Dave"}, {"name": "Linda May", "character": "Linda"}, {"name": "Swankie", "character": "Swankie"}, {"name": "Gay DeForest", "character": "Gay"}]', 'Chloé Zhao', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (531, 'tt6723592', 577922, 'Tenet', 2020, '/aCIFMriQh8rvhxpN1IWGgvH0Tlg.jpg', '{28,53,878}', 'Armed with only one word - Tenet - and fighting for the survival of the entire world, the Protagonist journeys through a twilight world of international espionage on a mission that will unfold in something beyond real time.', '[{"name": "John David Washington", "character": "Protagonist"}, {"name": "Robert Pattinson", "character": "Neil"}, {"name": "Elizabeth Debicki", "character": "Kat"}, {"name": "Kenneth Branagh", "character": "Sator"}, {"name": "Dimple Kapadia", "character": "Priya"}]', 'Christopher Nolan', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (532, 'tt6710474', 545611, 'Everything Everywhere All at Once', 2022, '/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', '{28,12,878}', 'An aging Chinese immigrant is swept up in an insane adventure, where she alone can save what''s important to her by connecting with the lives she could have led in other universes.', '[{"name": "Michelle Yeoh", "character": "Evelyn Wang"}, {"name": "Stephanie Hsu", "character": "Joy Wang / Jobu Tupaki"}, {"name": "Ke Huy Quan", "character": "Waymond Wang"}, {"name": "James Hong", "character": "Gong Gong"}, {"name": "Jamie Lee Curtis", "character": "Deirdre Beaubeirdre"}]', 'Daniel Scheinert', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (533, 'tt11813216', 674324, 'The Banshees of Inisherin', 2022, '/4yFG6cSPaCaPhyJ1vtGOtMD1lgh.jpg', '{18,35}', 'Two lifelong friends find themselves at an impasse when one abruptly ends their relationship, with alarming consequences for both of them.', '[{"name": "Colin Farrell", "character": "Pádraic Súilleabháin"}, {"name": "Brendan Gleeson", "character": "Colm Doherty"}, {"name": "Kerry Condon", "character": "Siobhán Súilleabháin"}, {"name": "Barry Keoghan", "character": "Dominic Kearney"}, {"name": "Gary Lydon", "character": "Peadar Kearney"}]', 'Martin McDonagh', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (534, 'tt1517268', 346698, 'Barbie', 2023, '/iuFNMS8U5cb6xfzi51Dbkovj7vM.jpg', '{35,12,14}', 'Barbie and Ken are having the time of their lives in the colorful and seemingly perfect world of Barbie Land. However, when they get a chance to go to the real world, they soon discover the joys and perils of living among humans.', '[{"name": "Margot Robbie", "character": "Barbie"}, {"name": "Ryan Gosling", "character": "Ken"}, {"name": "America Ferrera", "character": "Gloria"}, {"name": "Ariana Greenblatt", "character": "Sasha"}, {"name": "Issa Rae", "character": "Barbie"}]', 'Greta Gerwig', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (535, 'tt14230458', 792307, 'Poor Things', 2023, '/kCGlIMHnOm8JPXq3rXM6c5wMxcT.jpg', '{878,10749,35}', 'Brought back to life by an unorthodox scientist, a young woman runs off with a lawyer on a whirlwind adventure across the continents. Free from the prejudices of her times, she grows steadfast in her purpose to stand for equality and liberation.', '[{"name": "Emma Stone", "character": "Bella Baxter"}, {"name": "Mark Ruffalo", "character": "Duncan Wedderburn"}, {"name": "Willem Dafoe", "character": "Godwin Baxter"}, {"name": "Ramy Youssef", "character": "Max McCandles"}, {"name": "Christopher Abbott", "character": "Alfie Blessington"}]', 'Yorgos Lanthimos', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (536, 'tt0080339', 813, 'Airplane!', 1980, '/7Q3efxd3AF1vQjlSxnlerSA7RzN.jpg', '{35}', 'An ex-fighter pilot forced to take over the controls of an airliner when the flight crew succumbs to food poisoning.', '[{"name": "Robert Hays", "character": "Ted Striker"}, {"name": "Julie Hagerty", "character": "Elaine Dickinson"}, {"name": "Leslie Nielsen", "character": "Dr. Rumack"}, {"name": "Kareem Abdul-Jabbar", "character": "Roger Murdock"}, {"name": "Lloyd Bridges", "character": "Steve McCroskey"}]', 'Jerry Zucker', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (537, 'tt0087538', 1885, 'The Karate Kid', 1984, '/1mp4ViklKvA0WXXsNvNx0RBuiit.jpg', '{28,18,10751}', 'New Jersey teen Daniel LaRusso moves to Los Angeles with his mother, and soon strikes up a relationship with Ali. He quickly finds himself the target of bullying by a group of thugs, led by Ali''s ex-boyfriend Johnny, who study karate at the Cobra Kai dojo under ruthless sensei John Kreese. Fortunately, Daniel befriends Mr. Miyagi, an unassuming repairman who just happens to be a martial arts master himself. Miyagi takes Daniel under his wing, training him in a more compassionate form of karate for self-defense and, later, preparing him to compete against the brutal Cobra Kai.', '[{"name": "Ralph Macchio", "character": "Daniel"}, {"name": "Pat Morita", "character": "Miyagi"}, {"name": "Elisabeth Shue", "character": "Ali"}, {"name": "William Zabka", "character": "Johnny"}, {"name": "Martin Kove", "character": "Kreese"}]', 'John G. Avildsen', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (538, 'tt0087800', 377, 'A Nightmare on Elm Street', 1984, '/b9rMHAAKISRmIonaQd9Cccx0S4X.jpg', '{27}', 'Teenagers in a small town are dropping like flies, apparently in the grip of mass hysteria causing their suicides. A cop''s daughter, Nancy Thompson, traces the cause to child molester Fred Krueger, who was burned alive by angry parents many years before. Krueger has now come back in the dreams of his killers'' children, claiming their lives as his revenge. Nancy and her boyfriend, Glen, must devise a plan to lure the monster out of the realm of nightmares and into the real world...', '[{"name": "Heather Langenkamp", "character": "Nancy Thompson"}, {"name": "Johnny Depp", "character": "Glen Lantz"}, {"name": "Robert Englund", "character": "Fred Krueger"}, {"name": "Amanda Wyss", "character": "Tina Gray"}, {"name": "Jsu Garcia", "character": "Rod Lane"}]', 'Wes Craven', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (539, 'tt0089880', 1369, 'Rambo: First Blood Part II', 1985, '/fVwRtWqEPdsCH21BVDGqgkAQcff.jpg', '{28,12,53,10752}', 'John Rambo is released from prison by the government for a top-secret covert mission to the last place on Earth he''d want to return - the jungles of Vietnam.', '[{"name": "Sylvester Stallone", "character": "John J. Rambo"}, {"name": "Richard Crenna", "character": "Col. Samuel Trautman"}, {"name": "Charles Napier", "character": "Marshall Murdock"}, {"name": "Steven Berkoff", "character": "Lt. Col. Podovsky"}, {"name": "Julia Nickson", "character": "Co Bao"}]', 'George P. Cosmatos', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (540, 'tt0094898', 9602, 'Coming to America', 1988, '/8YZiA1o264dk0cr1USyMdph6SZl.jpg', '{35,10749}', 'An African prince decides it’s time for him to find a princess... and his mission leads him and his most loyal friend to Queens, New York. In disguise as an impoverished immigrant, the pampered prince quickly finds himself a new job, new friends, new digs, new enemies and lots of trouble.', '[{"name": "Eddie Murphy", "character": "Prince Akeem / Clarence / Randy Watson / Saul"}, {"name": "Arsenio Hall", "character": "Semmi / Extremely Ugly Girl / Morris / Reverend Brown"}, {"name": "Shari Headley", "character": "Lisa McDowell"}, {"name": "John Amos", "character": "Cleo McDowell"}, {"name": "James Earl Jones", "character": "King Jaffe Joffer"}]', 'John Landis', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (541, 'tt0093409', 941, 'Lethal Weapon', 1987, '/fTq4ThIP3pQTYR9eDepsbDHqdcs.jpg', '{28,53,80}', 'A veteran cop and an unstable detective become partners who must put their differences aside in order to bring down a heroin-smuggling ring run by ex-Special Forces.', '[{"name": "Mel Gibson", "character": "Martin Riggs"}, {"name": "Danny Glover", "character": "Roger Murtaugh"}, {"name": "Gary Busey", "character": "Mr. Joshua"}, {"name": "Mitchell Ryan", "character": "General Peter McAllister"}, {"name": "Tom Atkins", "character": "Michael Hunsaker"}]', 'Richard Donner', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (542, 'tt0094291', 10673, 'Wall Street', 1987, '/2tQYq9ntzn2dEwDIGLBSipYPenv.jpg', '{80,18}', 'A young and impatient stockbroker is willing to do anything to get to the top, including trading on illegal inside information taken through a ruthless and greedy corporate raider, whom takes the youth under his wing.', '[{"name": "Michael Douglas", "character": "Gordon Gekko"}, {"name": "Charlie Sheen", "character": "Bud Fox"}, {"name": "Martin Sheen", "character": "Carl Fox"}, {"name": "Daryl Hannah", "character": "Darien Taylor"}, {"name": "John C. McGinley", "character": "Marvin"}]', 'Oliver Stone', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (543, 'tt0096463', 3525, 'Working Girl', 1988, '/q2jfFzZvAzjTaArQR0tjilIZ5aJ.jpg', '{35,10749,18}', 'When a secretary''s idea is stolen by her boss, she takes a risky chance to reclaim it by impersonating him and running the project from his position.', '[{"name": "Melanie Griffith", "character": "Tess McGill"}, {"name": "Harrison Ford", "character": "Jack Trainer"}, {"name": "Sigourney Weaver", "character": "Katharine Parker"}, {"name": "Alec Baldwin", "character": "Mick Dugan"}, {"name": "Joan Cusack", "character": "Cyn"}]', 'Mike Nichols', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (544, 'tt0092890', 88, 'Dirty Dancing', 1987, '/9Jw6jys7q9gjzVX5zm1z0gC8gY9.jpg', '{18,10402,10749}', 'Expecting the usual tedium that accompanies a summer in the Catskills with her family, 17-year-old Frances ''Baby'' Houseman is surprised to find herself stepping into the shoes of a professional hoofer—and unexpectedly falling in love.', '[{"name": "Jennifer Grey", "character": "Frances \"Baby\" Houseman"}, {"name": "Patrick Swayze", "character": "Johnny Castle"}, {"name": "Cynthia Rhodes", "character": "Penny Johnson"}, {"name": "Neal Jones", "character": "Billy Kostecki"}, {"name": "Jerry Orbach", "character": "Dr. Jake Houseman"}]', 'Emile Ardolino', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (545, 'tt0097757', 10144, 'The Little Mermaid', 1989, '/plcZXvI310FkbwIptvd6rqk63LP.jpg', '{16,10751,14}', 'This colorful adventure tells the story of an impetuous mermaid princess named Ariel who falls in love with the very human Prince Eric and puts everything on the line for the chance to be with him. Memorable songs and characters -- including the villainous sea witch Ursula.', '[{"name": "Jodi Benson", "character": "Ariel (voice)"}, {"name": "Samuel E. Wright", "character": "Sebastian (voice)"}, {"name": "Pat Carroll", "character": "Ursula (voice)"}, {"name": "Christopher Daniel Barnes", "character": "Eric (voice)"}, {"name": "Kenneth Mars", "character": "Triton (voice)"}]', 'John Musker', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (546, 'tt0099674', 242, 'The Godfather Part III', 1990, '/lm3pQ2QoQ16pextRsmnUbG2onES.jpg', '{80,18,53}', 'In the midst of trying to legitimize his business dealings in 1979 New York and Italy, aging mafia don, Michael Corleone seeks forgiveness for his sins while taking a young protege under his wing.', '[{"name": "Al Pacino", "character": "Michael Corleone"}, {"name": "Diane Keaton", "character": "Kay Adams"}, {"name": "Talia Shire", "character": "Connie Corleone Rizzi"}, {"name": "Andy Garcia", "character": "Vincent Mancini"}, {"name": "Eli Wallach", "character": "Don Altobello"}]', 'Francis Ford Coppola', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (547, 'tt0100405', 114, 'Pretty Woman', 1990, '/hVHUfT801LQATGd26VPzhorIYza.jpg', '{10749,35}', 'Vivian is a carefree, streetwise diamond in the rough when she meets sophisticated billionaire Edward in a chance encounter that turns into a week-long business arrangement. But Vivian''s energetic spirit challenges Edward''s no-nonsense approach to life, and soon they are teaching each other – and falling in love!', '[{"name": "Richard Gere", "character": "Edward Lewis"}, {"name": "Julia Roberts", "character": "Vivian Ward"}, {"name": "Ralph Bellamy", "character": "James Morse"}, {"name": "Jason Alexander", "character": "Philip Stuckey"}, {"name": "Laura San Giacomo", "character": "Kit De Luca"}]', 'Garry Marshall', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (548, 'tt0102685', 1089, 'Point Break', 1991, '/tlbERIghrQ4oofqlbF7H0K0EYnx.jpg', '{28,53,80}', 'In Los Angeles, a gang of bank robbers who call themselves The Ex-Presidents commit their crimes while wearing masks of Reagan, Carter, Nixon and Johnson. Believing that the members of the gang could be surfers, the F.B.I. sends young agent Johnny Utah to the beach undercover to mix with the surfers and gather information.', '[{"name": "Keanu Reeves", "character": "Agent Johnny Utah"}, {"name": "Patrick Swayze", "character": "Bodhi / Mask President"}, {"name": "Lori Petty", "character": "Tyler Endicott"}, {"name": "Gary Busey", "character": "Agent Angelo Pappas"}, {"name": "John C. McGinley", "character": "SAIC Ben Harp"}]', 'Kathryn Bigelow', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (549, 'tt0107614', 788, 'Mrs. Doubtfire', 1993, '/shHrSmXS5140o6sQzgzXxn3KqSm.jpg', '{35,18,10751}', 'Loving but irresponsible dad Daniel Hillard, estranged from his exasperated spouse, is crushed by a court order allowing only weekly visits with his kids. When Daniel learns his ex needs a housekeeper, he gets the job -- disguised as a British nanny. Soon he becomes not only his children''s best pal but the kind of parent he should have been from the start.', '[{"name": "Robin Williams", "character": "Daniel Hillard / Mrs. Doubtfire"}, {"name": "Sally Field", "character": "Miranda Hillard"}, {"name": "Lisa Jakub", "character": "Lydia Hillard"}, {"name": "Matthew Lawrence", "character": "Chris Hillard"}, {"name": "Mara Wilson", "character": "Natalie Hillard"}]', 'Chris Columbus', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (550, 'tt0108160', 858, 'Sleepless in Seattle', 1993, '/jAXfku1u1uaLGh4cUmK0ESf1pPu.jpg', '{35,18,10749}', 'After the death of his mother, a young boy calls a radio station in an attempt to set his father up on a date. Across the country, an engaged woman becomes convinced that they belong together, despite their never having met. Will their paths collide despite the odds?', '[{"name": "Meg Ryan", "character": "Annie Reed"}, {"name": "Tom Hanks", "character": "Sam Baldwin"}, {"name": "Ross Malinger", "character": "Jonah Baldwin"}, {"name": "Bill Pullman", "character": "Walter"}, {"name": "Rosie O''Donnell", "character": "Becky"}]', 'Nora Ephron', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (551, 'tt0109040', 3049, 'Ace Ventura: Pet Detective', 1994, '/pqiRuETmuSybfnVZ7qyeoXhQyN1.jpg', '{35,80,9648}', 'He''s Ace Ventura: Pet Detective. The Ace is on the case to find the Miami Dolphins'' missing mascot and quarterback Dan Marino. He goes eyeball to eyeball with a man-eating shark, stakes out the Miami Dolphins and woos and wows the ladies. Whether he''s undercover, under fire or underwater, he always gets his man… or beast!', '[{"name": "Jim Carrey", "character": "Ace Ventura"}, {"name": "Courteney Cox", "character": "Melissa Robinson"}, {"name": "Sean Young", "character": "Lt. Lois Einhorn"}, {"name": "Tone Loc", "character": "Emilio"}, {"name": "Dan Marino", "character": "Dan Marino"}]', 'Tom Shadyac', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (552, 'tt0110475', 854, 'The Mask', 1994, '/jPC2eYub74zwf2tPGVtzSlBW6Oy.jpg', '{35,14,80,10749}', 'Timid bank clerk Stanley Ipkiss discovers a magical mask infused with the spirit of the Norse god Loki. Donning it transforms him into an unrestrained, green-faced, cartoon-like wild man. While the mask grants him the confidence to woo a local singer, it also makes him the target of a ruthless mobster.', '[{"name": "Jim Carrey", "character": "Stanley Ipkiss / The Mask"}, {"name": "Peter Riegert", "character": "Mitch Kellaway"}, {"name": "Peter Greene", "character": "Dorian Tyrrell"}, {"name": "Amy Yasbeck", "character": "Peggy Brandt"}, {"name": "Richard Jeni", "character": "Charlie Schumaker"}]', 'Chuck Russell', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (553, 'tt0109686', 8467, 'Dumb and Dumber', 1994, '/4LdpBXiCyGKkR8FGHgjKlphrfUc.jpg', '{35}', 'Lloyd and Harry are two men whose stupidity is really indescribable. When Mary, a beautiful woman, loses an important suitcase with money before she leaves for Aspen, the two friends (who have found the suitcase) decide to return it to her. After some "adventures" they finally get to Aspen where, using the lost money they live it up and fight for Mary''s heart.', '[{"name": "Jim Carrey", "character": "Lloyd Christmas"}, {"name": "Jeff Daniels", "character": "Harry Dunne"}, {"name": "Lauren Holly", "character": "Mary Swanson"}, {"name": "Teri Garr", "character": "Helen Swanson"}, {"name": "Charles Rocket", "character": "Nicholas Andre"}]', 'Peter Farrelly', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (554, 'tt0117998', 664, 'Twister', 1996, '/d4ie3f6QTvNw40V770Uzo87SDZn.jpg', '{28,12,18}', 'An unprecedented series of violent tornadoes is sweeping across Oklahoma. Tornado chasers, headed by Dr. Jo Harding, attempt to release a groundbreaking device that will allow them to track them and create a more advanced warning system. They are joined by Jo''s soon to be ex-husband Bill, a former tornado chaser himself, and his girlfriend Melissa.', '[{"name": "Helen Hunt", "character": "Jo"}, {"name": "Bill Paxton", "character": "Bill"}, {"name": "Jami Gertz", "character": "Melissa"}, {"name": "Cary Elwes", "character": "Jonas"}, {"name": "Lois Smith", "character": "Aunt Meg"}]', 'Jan de Bont', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (555, 'tt0117500', 9802, 'The Rock', 1996, '/eBcoxveWzzXQrCrwWMGAROcqgpP.jpg', '{28,12,53}', 'When vengeful General Francis X. Hummel seizes control of Alcatraz Island and threatens to launch missiles loaded with deadly chemical weapons into San Francisco, only a young FBI chemical weapons expert and notorious Federal prisoner have the skills to penetrate the impregnable island fortress and take him down.', '[{"name": "Sean Connery", "character": "John Patrick Mason"}, {"name": "Nicolas Cage", "character": "Dr. Stanley Goodspeed"}, {"name": "Ed Harris", "character": "Brigadier General Francis X. Hummel, USMC"}, {"name": "John Spencer", "character": "FBI Director James Womack"}, {"name": "David Morse", "character": "Major Tom Baxter"}]', 'Michael Bay', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (556, 'tt0117060', 954, 'Mission: Impossible', 1996, '/l5uxY5m5OInWpcExIpKG6AR3rgL.jpg', '{12,28,53}', 'When Ethan Hunt, the leader of a crack espionage team whose perilous operation has gone awry with no explanation, discovers that a mole has penetrated the CIA, he''s surprised to learn that he''s the prime suspect. To clear his name, Hunt now must ferret out the real double agent and, in the process, even the score.', '[{"name": "Tom Cruise", "character": "Ethan Hunt"}, {"name": "Jon Voight", "character": "Jim Phelps"}, {"name": "Emmanuelle Béart", "character": "Claire"}, {"name": "Henry Czerny", "character": "Kittridge"}, {"name": "Jean Reno", "character": "Krieger"}]', 'Brian De Palma', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (557, 'tt0119738', 8874, 'My Best Friend''s Wedding', 1997, '/b5g4bp8gS5ovMyR5439AII6zQ3n.jpg', '{35,10749}', 'When she receives word that her longtime platonic pal Michael O''Neal is getting married to debutante Kimberly Wallace, food critic Julianne Potter realizes her true feelings for Michael -- and sets out to sabotage the wedding.', '[{"name": "Julia Roberts", "character": "Julianne Potter"}, {"name": "Dermot Mulroney", "character": "Michael O''Neal"}, {"name": "Cameron Diaz", "character": "Kimmy Wallace"}, {"name": "Rupert Everett", "character": "George Downes"}, {"name": "Philip Bosco", "character": "Walter Wallace"}]', 'P.J. Hogan', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (558, 'tt0119094', 754, 'Face/Off', 1997, '/69Xzn8UdPbVnmqSChKz2RTpoNfB.jpg', '{28,80,878}', 'In order to foil a terrorist plot, an FBI agent undergoes facial transplant surgery and assumes the identity of a criminal mastermind. The plan turns sour when the criminal wakes up prematurely and seeks revenge.', '[{"name": "John Travolta", "character": "Sean Archer"}, {"name": "Nicolas Cage", "character": "Castor Troy"}, {"name": "Joan Allen", "character": "Eve Archer"}, {"name": "Alessandro Nivola", "character": "Pollux Troy"}, {"name": "Gina Gershon", "character": "Sasha Hassler"}]', 'John Woo', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (559, 'tt0118571', 9772, 'Air Force One', 1997, '/evO1iENjLpUnbwjnt5XK85jRYob.jpg', '{28,53}', 'When Russian neo-nationalists hijack Air Force One, the world''s most secure and extraordinary aircraft, the President is faced with a nearly impossible decision to give in to terrorist demands or sacrifice not only the country''s dignity, but the lives of his wife and daughter.', '[{"name": "Harrison Ford", "character": "James Marshall"}, {"name": "Gary Oldman", "character": "Ivan Korshunov"}, {"name": "Glenn Close", "character": "Kathryn Bennett"}, {"name": "Wendy Crewson", "character": "Grace Marshall"}, {"name": "Liesel Matthews", "character": "Alice Marshall"}]', 'Wolfgang Petersen', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (560, 'tt0118880', 1701, 'Con Air', 1997, '/kOKjgrEzGOP92rVQ6srA9jtp60l.jpg', '{28,53,80}', 'Newly-paroled former US Army ranger Cameron Poe is headed back to his wife, but must fly home aboard a prison transport flight dubbed "Jailbird" taking the “worst of the worst” prisoners, a group described as “pure predators”, to a new super-prison. Poe faces impossible odds when the transport plane is skyjacked mid-flight by the most vicious criminals in the country led by the mastermind — genius serial killer Cyrus "The Virus" Grissom, and backed by black militant Diamond Dog and psychopath Billy Bedlam.', '[{"name": "Nicolas Cage", "character": "Cameron Poe"}, {"name": "John Cusack", "character": "Agent Vince Larkin"}, {"name": "John Malkovich", "character": "Cyrus \"The Virus\" Grissom"}, {"name": "Ving Rhames", "character": "Nathan \"Diamond Dog\" Jones"}, {"name": "Mykelti Williamson", "character": "\"Baby-O\" O''Dell"}]', 'Simon West', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (561, 'tt0129387', 544, 'There''s Something About Mary', 1998, '/slJD1Dvnsf15LoeqhERsyzisAdn.jpg', '{10749,35}', 'For Ted, prom night went about as bad as it’s possible for any night to go. Thirteen years later, he finally gets another chance with his old prom date, only to run up against other suitors including the sleazy detective he hired to find her.', '[{"name": "Cameron Diaz", "character": "Mary Jensen"}, {"name": "Matt Dillon", "character": "Pat Healy"}, {"name": "Ben Stiller", "character": "Ted Stroehmann"}, {"name": "Lee Evans", "character": "Tucker"}, {"name": "Chris Elliott", "character": "Dom Woganowski"}]', 'Bobby Farrelly', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (562, 'tt0120762', 10674, 'Mulan', 1998, '/jAbexAtB0aSfP5Ay4TpWHARyVnG.jpg', '{16,10751,12}', 'When Imperial China calls one man from every family to defend the empire from invading Huns, a young woman disguises herself as a soldier to take her ailing father’s place. Facing ruthless invaders, brutal training, and the risk of execution if discovered, she must decide who she truly is— and what she’s willing to fight for.', '[{"name": "Ming-Na Wen", "character": "Mulan (voice)"}, {"name": "Eddie Murphy", "character": "Mushu (voice)"}, {"name": "BD Wong", "character": "Shang (voice)"}, {"name": "Miguel Ferrer", "character": "Shan-Yu (voice)"}, {"name": "Harvey Fierstein", "character": "Yao (voice)"}]', 'Tony Bancroft', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (563, 'tt0128853', 9489, 'You''ve Got Mail', 1998, '/e2uVtH6TpMfUl7WeOM70ezkcjsU.jpg', '{35,10749}', 'Book superstore magnate Joe Fox and independent book shop owner Kathleen Kelly fall in love in the anonymity of the Internet—both blissfully unaware that he''s trying to put her out of business.', '[{"name": "Meg Ryan", "character": "Kathleen Kelly"}, {"name": "Tom Hanks", "character": "Joe Fox"}, {"name": "Greg Kinnear", "character": "Frank Navasky"}, {"name": "Parker Posey", "character": "Patricia Eden"}, {"name": "Heather Burns", "character": "Christina Plutzker"}]', 'Nora Ephron', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (564, 'tt0163651', 2105, 'American Pie', 1999, '/5P68by2Thn8wHAziyWGEw2O7hco.jpg', '{35,10749}', 'At a high-school party, four friends find that losing their collective virginity isn''t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all "score" by their senior prom.', '[{"name": "Jason Biggs", "character": "Jim Levenstein"}, {"name": "Chris Klein", "character": "Chris ''Oz'' Ostreicher"}, {"name": "Thomas Ian Nicholas", "character": "Kevin Meyers"}, {"name": "Alyson Hannigan", "character": "Michelle Flaherty"}, {"name": "Shannon Elizabeth", "character": "Nadia"}]', 'Paul Weitz', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (565, 'tt0232500', 9799, 'The Fast and the Furious', 2001, '/gqY0ITBgT7A82poL9jv851qdnIb.jpg', '{28,80,53}', 'Dominic Toretto is a Los Angeles street racer suspected of masterminding a series of big-rig hijackings. When undercover cop Brian O''Conner infiltrates Toretto''s iconoclastic crew, he falls for Toretto''s sister and must choose a side: the gang or the LAPD.', '[{"name": "Paul Walker", "character": "Brian O''Conner"}, {"name": "Vin Diesel", "character": "Dominic Toretto"}, {"name": "Michelle Rodriguez", "character": "Letty Ortiz"}, {"name": "Jordana Brewster", "character": "Mia Toretto"}, {"name": "Rick Yune", "character": "Johnny Tran"}]', 'Rob Cohen', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (566, 'tt0250494', 8835, 'Legally Blonde', 2001, '/9ohlMrJHQqKhfUKh7Zr3JQqHNLZ.jpg', '{35}', 'Fashionable sorority queen Elle Woods has it all, but, she wants nothing more than to be Mrs. Warner Huntington III. But he dumps her before heading to Harvard Law School. Elle rallies all of her resources and gets into Harvard, determined to win him back. While there, she figures out that there is more to herself than just good looks.', '[{"name": "Reese Witherspoon", "character": "Elle Woods"}, {"name": "Luke Wilson", "character": "Emmetten Richmond"}, {"name": "Selma Blair", "character": "Vivian Kensington"}, {"name": "Matthew Davis", "character": "Warner Huntington III"}, {"name": "Victor Garber", "character": "Professor Callahan"}]', 'Robert Luketic', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (567, 'tt0196229', 9398, 'Zoolander', 2001, '/qdrbSneHZjJG2Dj0hhBxzzAo4HB.jpg', '{35}', 'Clear the runway for Derek Zoolander, VH1''s three-time male model of the year. His face falls when hippie-chic Hansel scooters in to steal this year''s award. The evil fashion guru Mugatu seizes the opportunity to turn Derek into a killing machine. It''s a well-designed conspiracy and only with the help of Hansel and a few well-chosen accessories like Matilda can Derek make the world safe for male models everywhere.', '[{"name": "Ben Stiller", "character": "Derek Zoolander"}, {"name": "Owen Wilson", "character": "Hansel"}, {"name": "Christine Taylor", "character": "Matilda Jeffries"}, {"name": "Will Ferrell", "character": "Mugatu"}, {"name": "Milla Jovovich", "character": "Katinka"}]', 'Ben Stiller', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (568, 'tt0120903', 36657, 'X-Men', 2000, '/bRDAc4GogyS9ci3ow7UnInOcriN.jpg', '{12,28,878}', 'Two mutants, Rogue and Wolverine, come to a private academy for their kind whose resident superhero team, the X-Men, must oppose a terrorist organization with similar powers.', '[{"name": "Hugh Jackman", "character": "Logan / Wolverine"}, {"name": "Patrick Stewart", "character": "Xavier"}, {"name": "Ian McKellen", "character": "Magneto"}, {"name": "Famke Janssen", "character": "Jean Grey"}, {"name": "James Marsden", "character": "Cyclops"}]', 'Bryan Singer', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (569, 'tt0290334', 36658, 'X2', 2003, '/bst4alFUXCxISwdRUKSMhhkrX1M.jpg', '{12,28,878}', 'Professor Charles Xavier and his team of genetically gifted superheroes face a rising tide of anti-mutant sentiment led by Col. William Stryker. Storm, Wolverine and Jean Grey must join Magneto and Mystique to unhinge Stryker''s scheme to exterminate all mutants.', '[{"name": "Hugh Jackman", "character": "Logan / Wolverine"}, {"name": "Patrick Stewart", "character": "Professor Charles Xavier"}, {"name": "Ian McKellen", "character": "Eric Lehnsherr / Magneto"}, {"name": "James Marsden", "character": "Scott Summers / Cyclops"}, {"name": "Brian Cox", "character": "William Stryker"}]', 'Bryan Singer', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (570, 'tt0298130', 565, 'The Ring', 2002, '/AeRpUynJKDpJveklBJipOYrVxCS.jpg', '{27,9648}', 'Journalist Rachel Keller investigates a strange videotape that may be behind the untimely deaths of four teenagers. There is an urban legend about this tape: the viewer will die seven days after watching it. Rachel tracks down the video... and watches it. Now she has just seven days to unravel the mystery of the Ring in order to save herself and her son.', '[{"name": "Naomi Watts", "character": "Rachel Keller"}, {"name": "Martin Henderson", "character": "Noah Clay"}, {"name": "David Dorfman", "character": "Aidan Keller"}, {"name": "Brian Cox", "character": "Richard Morgan"}, {"name": "Jane Alexander", "character": "Dr. Grasnik"}]', 'Gore Verbinski', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (571, 'tt0268380', 425, 'Ice Age', 2002, '/gLhHHZUzeseRXShoDyC4VqLgsNv.jpg', '{16,35,10751,12}', 'Manny the mammoth, Sid the loquacious sloth, and Diego the sabre-toothed tiger go on a comical quest to return a human baby back to his father, across a world on the brink of an ice age.', '[{"name": "Ray Romano", "character": "Manfred ''Manny'' (voice)"}, {"name": "John Leguizamo", "character": "Sid (voice)"}, {"name": "Denis Leary", "character": "Diego (voice)"}, {"name": "Goran Višnjić", "character": "Soto (voice)"}, {"name": "Jack Black", "character": "Zeke (voice)"}]', 'Chris Wedge', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (572, 'tt0289043', 170, '28 Days Later', 2002, '/sQckQRt17VaWbo39GIu0TMOiszq.jpg', '{27,53,878}', 'Twenty-eight days after a killer virus was accidentally unleashed from a British research facility, a small group of London survivors are caught in a desperate struggle to protect themselves from the infected. Carried by animals and humans, the virus turns those it infects into homicidal maniacs -- and it''s absolutely impossible to contain.', '[{"name": "Cillian Murphy", "character": "Jim"}, {"name": "Naomie Harris", "character": "Selena"}, {"name": "Brendan Gleeson", "character": "Frank"}, {"name": "Megan Burns", "character": "Hannah"}, {"name": "Christopher Eccleston", "character": "Major Henry West"}]', 'Danny Boyle', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (573, 'tt0377092', 10625, 'Mean Girls', 2004, '/2ZkuQXvVhh45uSvkBej4S7Ix1NJ.jpg', '{18,35}', 'Cady Heron is a hit with The Plastics, the A-list girl clique at her new school, until she makes the mistake of falling for Aaron Samuels, the ex-boyfriend of alpha Plastic Regina George.', '[{"name": "Lindsay Lohan", "character": "Cady Heron"}, {"name": "Rachel McAdams", "character": "Regina George"}, {"name": "Lizzy Caplan", "character": "Janis Ian"}, {"name": "Lacey Chabert", "character": "Gretchen Wieners"}, {"name": "Amanda Seyfried", "character": "Karen Smith"}]', 'Mark Waters', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (574, 'tt0458352', 350, 'The Devil Wears Prada', 2006, '/8912AsVuS7Sj915apArUFbv6F9L.jpg', '{18,35}', 'A young woman from the Midwest gets more than she bargained for when she moves to New York to become a writer and ends up as the assistant to the tyrannical, larger-than-life editor-in-chief of a major fashion magazine.', '[{"name": "Meryl Streep", "character": "Miranda Priestly"}, {"name": "Anne Hathaway", "character": "Andy Sachs"}, {"name": "Emily Blunt", "character": "Emily"}, {"name": "Stanley Tucci", "character": "Nigel"}, {"name": "Simon Baker", "character": "Christian Thompson"}]', 'David Frankel', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (575, 'tt0357413', 8699, 'Anchorman: The Legend of Ron Burgundy', 2004, '/mhZIcRePT7U8viFQVjt1ZjYIsR4.jpg', '{35}', 'It''s the 1970s and San Diego anchorman Ron Burgundy is the top dog in local TV, but that''s all about to change when ambitious reporter Veronica Corningstone arrives as a new employee at his station.', '[{"name": "Will Ferrell", "character": "Ron Burgundy"}, {"name": "Christina Applegate", "character": "Veronica Corningstone"}, {"name": "Paul Rudd", "character": "Brian Fantana"}, {"name": "Steve Carell", "character": "Brick Tamland"}, {"name": "David Koechner", "character": "Champ Kind"}]', 'Adam McKay', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (576, 'tt0351283', 953, 'Madagascar', 2005, '/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg', '{12,16,35,10751}', 'Four animal friends get a taste of the wild life when they break out of captivity at the Central Park Zoo and wash ashore on the island of Madagascar.', '[{"name": "Ben Stiller", "character": "Alex (voice)"}, {"name": "Chris Rock", "character": "Marty (voice)"}, {"name": "David Schwimmer", "character": "Melman (voice)"}, {"name": "Jada Pinkett Smith", "character": "Gloria (voice)"}, {"name": "Sacha Baron Cohen", "character": "King Julien (voice)"}]', 'Eric Darnell', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (577, 'tt0317219', 920, 'Cars', 2006, '/2Touk3m5gzsqr1VsvxypdyHY5ci.jpg', '{16,12,35,10751}', 'Lightning McQueen, a hotshot rookie race car driven to succeed, discovers that life is about the journey, not the finish line, when he finds himself unexpectedly detoured in the sleepy Route 66 town of Radiator Springs. On route across the country to the big Piston Cup Championship in California to compete against two seasoned pros, McQueen gets to know the town''s offbeat characters.', '[{"name": "Owen Wilson", "character": "Lightning McQueen (voice)"}, {"name": "Paul Newman", "character": "Doc Hudson (voice)"}, {"name": "Bonnie Hunt", "character": "Sally Carrera (voice)"}, {"name": "Larry the Cable Guy", "character": "Mater (voice)"}, {"name": "Cheech Marin", "character": "Ramone (voice)"}]', 'John Lasseter', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (578, 'tt0418279', 1858, 'Transformers', 2007, '/4N4sipl8T72tNE4earcctQa2Kw2.jpg', '{12,878,28}', 'Young teenager Sam Witwicky becomes involved in the ancient struggle between two extraterrestrial factions of transforming robots – the heroic Autobots and the evil Decepticons. Sam holds the clue to unimaginable power and the Decepticons will stop at nothing to retrieve it.', '[{"name": "Shia LaBeouf", "character": "Sam Witwicky"}, {"name": "Megan Fox", "character": "Mikaela Banes"}, {"name": "Mark Ryan", "character": "Bumblebee (voice)"}, {"name": "Peter Cullen", "character": "Optimus Prime (voice)"}, {"name": "Hugo Weaving", "character": "Megatron (voice)"}]', 'Michael Bay', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (579, 'tt0829482', 8363, 'Superbad', 2007, '/ek8e8txUyUwd2BNqj6lFEerJfbq.jpg', '{35}', 'Two co-dependent high school seniors are forced to deal with separation anxiety after their plan to stage a booze-soaked party goes awry.', '[{"name": "Jonah Hill", "character": "Seth"}, {"name": "Michael Cera", "character": "Evan"}, {"name": "Christopher Mintz-Plasse", "character": "Fogell"}, {"name": "Bill Hader", "character": "Officer Slater"}, {"name": "Seth Rogen", "character": "Officer Michaels"}]', 'Greg Mottola', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (580, 'tt0441773', 9502, 'Kung Fu Panda', 2008, '/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg', '{28,16,35,10751}', 'Chosen by prophecy but doubted by all, Po is an unlikely choice for the mystical title of the Dragon Warrior—a clumsy panda thrust into the world of kung fu as a deadly enemy threatens the Valley of Peace. Under reluctant guidance by Master Shifu and the Furious Five, Po must embrace who he is to unlock the power that no scroll can teach.', '[{"name": "Jack Black", "character": "Po (voice)"}, {"name": "Dustin Hoffman", "character": "Master Shifu (voice)"}, {"name": "Angelina Jolie", "character": "Tigress (voice)"}, {"name": "Ian McShane", "character": "Tai Lung (voice)"}, {"name": "Seth Rogen", "character": "Mantis (voice)"}]', 'Mark Osborne', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (581, 'tt1099212', 8966, 'Twilight', 2008, '/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg', '{14,18,10749}', 'When Bella Swan moves to a small town in the Pacific Northwest, she falls in love with Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward''s repeated cautions, Bella can''t stay away from him, a fatal move that endangers her own life.', '[{"name": "Kristen Stewart", "character": "Bella Swan"}, {"name": "Robert Pattinson", "character": "Edward Cullen"}, {"name": "Billy Burke", "character": "Charlie Swan"}, {"name": "Peter Facinelli", "character": "Dr. Carlisle Cullen"}, {"name": "Ashley Greene", "character": "Alice Cullen"}]', 'Catherine Hardwicke', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (582, 'tt1228705', 10138, 'Iron Man 2', 2010, '/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg', '{12,28,878}', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James ''Rhodey'' Rhodes at his side, must forge new alliances – and confront powerful enemies.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark"}, {"name": "Gwyneth Paltrow", "character": "Pepper Potts"}, {"name": "Don Cheadle", "character": "Lt. Col. James ''Rhodey'' Rhodes"}, {"name": "Scarlett Johansson", "character": "Natalie Rushman / Natasha Romanoff"}, {"name": "Sam Rockwell", "character": "Justin Hammer"}]', 'Jon Favreau', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (583, 'tt1323594', 20352, 'Despicable Me', 2010, '/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg', '{16,35,80,878,10751}', 'Determined to prove he''s the world''s greatest supervillain, Gru hatches an audacious plan to steal the Moon. To pull it off, he adopts three orphaned girls—Margo, Edith, and Agnes—intending to use them as part of his scheme. But the unexpected bond they form forces him to question the life he''s always known.', '[{"name": "Steve Carell", "character": "Gru (voice)"}, {"name": "Jason Segel", "character": "Vector (voice)"}, {"name": "Russell Brand", "character": "Dr. Nefario (voice)"}, {"name": "Julie Andrews", "character": "Gru''s Mother (voice)"}, {"name": "Will Arnett", "character": "Mr. Perkins (voice)"}]', 'Pierre Coffin', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (584, 'tt0398286', 38757, 'Tangled', 2010, '/ym7Kst6a4uodryxqbGOxmewF235.jpg', '{16,10751,12}', 'Feisty teenager Rapunzel, who has long and magical hair, wants to go and see sky lanterns on her eighteenth birthday, but she''s bound to a tower by her overprotective mother. She strikes a deal with Flynn Rider, a charming wanted thief, and the duo set off on an action-packed escapade.', '[{"name": "Mandy Moore", "character": "Rapunzel (voice)"}, {"name": "Zachary Levi", "character": "Flynn Rider (voice)"}, {"name": "Donna Murphy", "character": "Mother Gothel (voice)"}, {"name": "Ron Perlman", "character": "Stabbington Brother (voice)"}, {"name": "M.C. Gainey", "character": "Captain of the Guard (voice)"}]', 'Byron Howard', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (585, 'tt1119646', 18785, 'The Hangover', 2009, '/A0uS9rHR56FeBtpjVki16M5xxSW.jpg', '{35}', 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can''t seem to locate their best friend, Doug – who''s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.', '[{"name": "Bradley Cooper", "character": "Phil Wenneck"}, {"name": "Ed Helms", "character": "Stu Price"}, {"name": "Zach Galifianakis", "character": "Alan Garner"}, {"name": "Justin Bartha", "character": "Doug Billings"}, {"name": "Heather Graham", "character": "Jade"}]', 'Todd Phillips', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (586, 'tt1155076', 38575, 'The Karate Kid', 2010, '/b1RBy3l297N0c7PHjlz35cClWju.jpg', '{28,12,18,10751}', '12-year-old Dre Parker could''ve been the most popular kid in Detroit, but his mother''s latest career move has landed him in China. Dre immediately falls for his classmate Mei Ying but the cultural differences make such a friendship impossible. Even worse, Dre''s feelings make him an enemy of the class bully, Cheng. With no friends in a strange land, Dre has nowhere to turn but maintenance man Mr. Han, who is a kung fu master. As Han teaches Dre that kung fu is not about punches and parries, but maturity and calm, Dre realizes that facing down the bullies will be the fight of his life.', '[{"name": "Jaden Smith", "character": "Dre Parker"}, {"name": "Jackie Chan", "character": "Mr. Han"}, {"name": "Taraji P. Henson", "character": "Sherry Parker"}, {"name": "Wenwen Han", "character": "Meiying"}, {"name": "Zac Wang", "character": "Cheng"}]', 'Harald Zwart', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (587, 'tt0800369', 10195, 'Thor', 2011, '/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg', '{12,14,28}', 'Against his father Odin''s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.', '[{"name": "Chris Hemsworth", "character": "Thor"}, {"name": "Natalie Portman", "character": "Jane Foster"}, {"name": "Tom Hiddleston", "character": "Loki"}, {"name": "Anthony Hopkins", "character": "Odin"}, {"name": "Stellan Skarsgård", "character": "Erik Selvig"}]', 'Kenneth Branagh', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (588, 'tt0458339', 1771, 'Captain America: The First Avenger', 2011, '/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg', '{28,12,878}', 'During World War II, Steve Rogers is a sickly man from Brooklyn who''s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler''s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.', '[{"name": "Chris Evans", "character": "Captain America / Steve Rogers"}, {"name": "Hayley Atwell", "character": "Peggy Carter"}, {"name": "Sebastian Stan", "character": "James Buchanan ''Bucky'' Barnes"}, {"name": "Tommy Lee Jones", "character": "Colonel Chester Phillips"}, {"name": "Hugo Weaving", "character": "Johann Schmidt / Red Skull"}]', 'Joe Johnston', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (589, 'tt1478338', 55721, 'Bridesmaids', 2011, '/gJtA7hYsBMQ7EM3sPBMUdBfU7a0.jpg', '{35,10749}', 'Annie''s life is a mess. But when she finds out her lifetime best friend is engaged, she simply must serve as Lillian''s maid of honor. Though lovelorn and broke, Annie bluffs her way through the expensive and bizarre rituals. With one chance to get it perfect, she’ll show Lillian and her bridesmaids just how far you’ll go for someone you love.', '[{"name": "Kristen Wiig", "character": "Annie"}, {"name": "Maya Rudolph", "character": "Lillian"}, {"name": "Rose Byrne", "character": "Helen"}, {"name": "Chris O''Dowd", "character": "Rhodes"}, {"name": "Melissa McCarthy", "character": "Megan"}]', 'Paul Feig', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (590, 'tt1229238', 56292, 'Mission: Impossible - Ghost Protocol', 2011, '/eRZTGx7GsiKqPch96k27LK005ZL.jpg', '{28,53,12}', 'Ethan Hunt and his team are racing against time to track down a dangerous terrorist named Hendricks, who has gained access to Russian nuclear launch codes and is planning a strike on the United States. An attempt to stop him ends in an explosion causing severe destruction to the Kremlin and the IMF to be implicated in the bombing, forcing the President to disavow them. No longer being aided by the government, Ethan and his team chase Hendricks around the globe, although they might still be too late to stop a disaster.', '[{"name": "Tom Cruise", "character": "Ethan Hunt"}, {"name": "Paula Patton", "character": "Jane"}, {"name": "Simon Pegg", "character": "Benji"}, {"name": "Jeremy Renner", "character": "Brandt"}, {"name": "Michael Nyqvist", "character": "Hendricks"}]', 'Brad Bird', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (591, 'tt1392170', 70160, 'The Hunger Games', 2012, '/yXCbOiVDCxO71zI7cuwBRXdftq8.jpg', '{878,12,28,53}', 'In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance.', '[{"name": "Jennifer Lawrence", "character": "Katniss Everdeen"}, {"name": "Josh Hutcherson", "character": "Peeta Mellark"}, {"name": "Liam Hemsworth", "character": "Gale Hawthorne"}, {"name": "Woody Harrelson", "character": "Haymitch Abernathy"}, {"name": "Elizabeth Banks", "character": "Effie Trinket"}]', 'Gary Ross', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (592, 'tt0948470', 1930, 'The Amazing Spider-Man', 2012, '/jexoNYnPd6vVrmygwF6QZmWPFdu.jpg', '{28,12,878}', 'Peter Parker is an outcast high schooler abandoned by his parents as a boy, leaving him to be raised by his Uncle Ben and Aunt May. Like most teenagers, Peter is trying to figure out who he is and how he got to be the person he is today. As Peter discovers a mysterious briefcase that belonged to his father, he begins a quest to understand his parents'' disappearance – leading him directly to Oscorp and the lab of Dr. Curt Connors, his father''s former partner. As Spider-Man is set on a collision course with Connors'' alter ego, The Lizard, Peter will make life-altering choices to use his powers and shape his destiny to become a hero.', '[{"name": "Andrew Garfield", "character": "Spider-Man / Peter Parker"}, {"name": "Emma Stone", "character": "Gwen Stacy"}, {"name": "Rhys Ifans", "character": "The Lizard / Dr. Curt Connors"}, {"name": "Denis Leary", "character": "Captain Stacy"}, {"name": "Martin Sheen", "character": "Uncle Ben"}]', 'Marc Webb', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (593, 'tt1217209', 62177, 'Brave', 2012, '/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', '{12,16,10751,14}', 'In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Merida''s quest — and serving as comic relief — are the kingdom''s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.', '[{"name": "Kelly Macdonald", "character": "Merida (voice)"}, {"name": "Emma Thompson", "character": "Elinor (voice)"}, {"name": "Billy Connolly", "character": "Fergus (voice)"}, {"name": "Julie Walters", "character": "The Witch (voice)"}, {"name": "Robbie Coltrane", "character": "Lord Dingwall (voice)"}]', 'Mark Andrews', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (594, 'tt1772341', 82690, 'Wreck-It Ralph', 2012, '/ihfvxPh5C4rV2WSKWs7k7rzxzzO.jpg', '{10751,16,35,12}', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', '[{"name": "John C. Reilly", "character": "Ralph (voice)"}, {"name": "Sarah Silverman", "character": "Vanellope (voice)"}, {"name": "Jack McBrayer", "character": "Felix (voice)"}, {"name": "Jane Lynch", "character": "Calhoun (voice)"}, {"name": "Alan Tudyk", "character": "King Candy (voice)"}]', 'Rich Moore', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (595, 'tt1300854', 68721, 'Iron Man 3', 2013, '/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg', '{28,12,878}', 'When Tony Stark''s world is torn apart by a formidable terrorist called the Mandarin, he starts an odyssey of rebuilding and retribution.', '[{"name": "Robert Downey Jr.", "character": "Tony Stark"}, {"name": "Gwyneth Paltrow", "character": "Pepper Potts"}, {"name": "Don Cheadle", "character": "Colonel James Rhodes"}, {"name": "Guy Pearce", "character": "Aldrich Killian"}, {"name": "Rebecca Hall", "character": "Maya Hansen"}]', 'Shane Black', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (596, 'tt0816711', 72190, 'World War Z', 2013, '/aCnVdvExw6UWSeQfr0tUH3jr4qG.jpg', '{28,27,878}', 'Life for former United Nations investigator Gerry Lane and his family seems content. Suddenly, the world is plagued by a mysterious infection turning whole human populations into rampaging mindless zombies. After barely escaping the chaos, Lane is persuaded to go on a mission to investigate this disease. What follows is a perilous trek around the world where Lane must brave horrific dangers and long odds to find answers before human civilization falls.', '[{"name": "Brad Pitt", "character": "Gerry Lane"}, {"name": "Mireille Enos", "character": "Karen Lane"}, {"name": "Daniella Kertesz", "character": "Segen"}, {"name": "James Badge Dale", "character": "Captain Speke"}, {"name": "Ludi Boeken", "character": "Jurgen Warmbrunn"}]', 'Marc Forster', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (597, 'tt2294629', 109445, 'Frozen', 2013, '/itAKcobTYGpYT8Phwjd8c9hleTo.jpg', '{16,10751,12,14}', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.', '[{"name": "Idina Menzel", "character": "Elsa (voice)"}, {"name": "Kristen Bell", "character": "Anna (voice)"}, {"name": "Jonathan Groff", "character": "Kristoff (voice)"}, {"name": "Josh Gad", "character": "Olaf (voice)"}, {"name": "Livvy Stubenrauch", "character": "Young Anna (voice)"}]', 'Chris Buck', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (598, 'tt0770828', 49521, 'Man of Steel', 2013, '/8GFtkImmK0K1VaUChR0n9O61CFU.jpg', '{28,12,878}', 'A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.', '[{"name": "Henry Cavill", "character": "Clark Kent / Kal-El"}, {"name": "Amy Adams", "character": "Lois Lane"}, {"name": "Michael Shannon", "character": "General Zod"}, {"name": "Diane Lane", "character": "Martha Kent"}, {"name": "Russell Crowe", "character": "Jor-El"}]', 'Zack Snyder', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (599, 'tt1457767', 138843, 'The Conjuring', 2013, '/wVYREutTvI2tmxr6ujrHT704wGF.jpg', '{27,53}', 'Paranormal investigators Ed and Lorraine Warren work to help a family terrorized by a dark presence in their farmhouse. Forced to confront a powerful entity, the Warrens find themselves caught in the most terrifying case of their lives.', '[{"name": "Vera Farmiga", "character": "Lorraine Warren"}, {"name": "Patrick Wilson", "character": "Ed Warren"}, {"name": "Lili Taylor", "character": "Carolyn Perron"}, {"name": "Ron Livingston", "character": "Roger Perron"}, {"name": "Hayley McFarland", "character": "Nancy"}]', 'James Wan', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (600, 'tt1596343', 51497, 'Fast Five', 2011, '/gEfQjjQwY7fh5bI4GlG0RrBu7Pz.jpg', '{28,53,80}', 'Former cop Brian O''Conner partners with ex-con Dom Toretto on the opposite side of the law. Since Brian and Mia Toretto broke Dom out of custody, they''ve blown across many borders to elude authorities. Now backed into a corner in Rio de Janeiro, they must pull one last job in order to gain their freedom.', '[{"name": "Vin Diesel", "character": "Dominic Toretto"}, {"name": "Paul Walker", "character": "Brian O''Conner"}, {"name": "Jordana Brewster", "character": "Mia Toretto"}, {"name": "Tyrese Gibson", "character": "Roman Pearce"}, {"name": "Ludacris", "character": "Tej Parker"}]', 'Justin Lin', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (601, 'tt1340138', 87101, 'Terminator Genisys', 2015, '/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg', '{878,28,53}', 'The year is 2029. John Connor, leader of the resistance continues the war against the machines. At the Los Angeles offensive, John''s fears of the unknown future begin to emerge when TECOM spies reveal a new plot by SkyNet that will attack him from both fronts; past and future, and will ultimately change warfare forever.', '[{"name": "Emilia Clarke", "character": "Sarah Connor"}, {"name": "Jai Courtney", "character": "Kyle Reese"}, {"name": "Arnold Schwarzenegger", "character": "Guardian / The Terminator"}, {"name": "Jason Clarke", "character": "John Connor"}, {"name": "Matt Smith", "character": "Alex / Skynet"}]', 'Alan Taylor', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (602, 'tt0369610', 135397, 'Jurassic World', 2015, '/rhr4y79GpxQF9IsfJItRXVaoGs4.jpg', '{12,878,53}', 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.', '[{"name": "Chris Pratt", "character": "Owen"}, {"name": "Bryce Dallas Howard", "character": "Claire"}, {"name": "Irrfan Khan", "character": "Masrani"}, {"name": "Vincent D''Onofrio", "character": "Hoskins"}, {"name": "Ty Simpkins", "character": "Gray"}]', 'Colin Trevorrow', NULL, '2026-07-22 12:00:00.000000');
INSERT INTO public.quiz_movie_pool (id, "imdbId", "tmdbId", title, "releaseYear", "posterPath", genres, overview, "cast", director, "usedAt", "createdAt") VALUES (603, 'tt0478970', 102899, 'Ant-Man', 2015, '/rQRnQfUl3kfp78nCWq8Ks04vnq1.jpg', '{878,12,28}', 'Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.', '[{"name": "Paul Rudd", "character": "Scott Lang / Ant-Man"}, {"name": "Michael Douglas", "character": "Dr. Hank Pym"}, {"name": "Evangeline Lilly", "character": "Hope van Dyne"}, {"name": "Corey Stoll", "character": "Darren Cross / Yellowjacket"}, {"name": "Bobby Cannavale", "character": "Paxton"}]', 'Peyton Reed', NULL, '2026-07-22 12:00:00.000000');
