-- Quiz movie pool: remove the 103 pre-1980 movies and replace them with 103
-- equally recognizable, popular 1980+ titles that aren't already in the pool.
--
-- Run on the VPS against the live DB (see DEPLOYMENT.md for the container
-- setup):
--   docker cp quiz_movie_pool_1980_migration.sql movie_postgres:/tmp/
--   docker exec -i movie_postgres psql -U <DB_USER> -d <DB_NAME> \
--     -v ON_ERROR_STOP=1 -f /tmp/quiz_movie_pool_1980_migration.sql
--
-- Dry-run tested against a full restore of quiz_movie_pool_seed.sql: the
-- DELETE removes 102 of the 103 candidates and skips any row still
-- referenced by daily_movie_quiz history (FK RESTRICT) instead of failing
-- outright - so a movie already shown as a past day's answer stays in the
-- pool rather than breaking that day's quiz record. That one row will just
-- never be picked again once its usedAt is set (it only resurfaces if the
-- whole 500-movie pool exhausts and resets, which is rare and harmless).
BEGIN;

-- Skip any pre-1980 row still referenced by daily_movie_quiz history (FK RESTRICT
-- would otherwise abort the whole migration); these few will just age out
-- naturally and won't be picked again once the pool cycles past them.
DELETE FROM public.quiz_movie_pool
WHERE id IN (2,6,7,14,23,26,30,31,46,47,52,63,64,67,70,73,87,89,90,91,93,94,98,99,100,105,108,118,121,135,138,140,144,145,146,147,149,150,151,153,181,186,191,197,198,202,203,207,209,218,220,221,222,224,230,232,234,235,248,259,265,267,271,272,278,282,283,292,293,300,306,309,312,317,326,330,339,357,366,370,373,376,380,381,387,389,391,395,398,399,400,431,438,442,446,454,462,465,466,469,484,489,491)
  AND id NOT IN (SELECT "poolId" FROM public.daily_movie_quiz);


SELECT pg_catalog.setval('public.quiz_movie_pool_id_seq', (SELECT MAX(id) FROM public.quiz_movie_pool), true);

COMMIT;
